UPDATE programmes SET title_en='CENTRAL ASIA’S LARGEST STARTUP, ACCELERATOR & INVESTOR EVENT',title_ru='КРУПНЕЙШЕЕ В ЦЕНТРАЛЬНОЙ АЗИИ СОБЫТИЕ ДЛЯ СТАРТАПОВ И ИНВЕСТОРОВ',body_en='Central Asia & the Caucasus’ leading startup exhibition, connecting founders and enablers, with the Supernova Pitch Competition at its core.',body_ru='Ведущая выставка стартапов Центральной Азии и Кавказа, объединяющая основателей, инвесторов и партнёров вокруг конкурса Supernova Pitch.' WHERE sort_order=1;
UPDATE programmes SET title_en='CONNECT WITH THE PIONEERS POWERING THE NEXT WAVE OF AI BREAKTHROUGHS',title_ru='ВСТРЕЧАЙТЕСЬ С ЛИДЕРАМИ НОВОЙ ВОЛНЫ ПРОРЫВОВ В ИИ',body_en='The region’s flagship AI platform, showcasing applied AI, sovereign infrastructure and real-world use cases shaping next-generation digital economies.\nPlug into Central Asia’s fast-emerging AI & GenAI ecosystem; with Kazakhstan targeting US$5B in AI solution exports by 2029 and regional programs seeding dozens of AI startups.',body_ru='Флагманская платформа региона демонстрирует прикладной ИИ, суверенную инфраструктуру и реальные сценарии, формирующие цифровую экономику нового поколения.\nПрисоединяйтесь к быстрорастущей экосистеме ИИ и генеративного ИИ Центральной Азии.' WHERE sort_order=2;
UPDATE programmes SET title_en='STRENGTHENING PUBLIC-PRIVATE SYNERGY IN CYBERSECURITY ACROSS CENTRAL ASIA.',title_ru='УКРЕПЛЕНИЕ ГОСУДАРСТВЕННО-ЧАСТНОГО ПАРТНЁРСТВА В КИБЕРБЕЗОПАСНОСТИ ЦЕНТРАЛЬНОЙ АЗИИ',body_en='A dedicated cybersecurity zone uniting governments, enterprises and solution providers to strengthen digital trust, resilience and critical infrastructure security.',body_ru='Специализированная зона кибербезопасности объединяет государство, бизнес и поставщиков решений для укрепления цифрового доверия и защиты критической инфраструктуры.' WHERE sort_order=3;
UPDATE programmes SET title_en='ADVANCING SMART, SUSTAINABLE SOLUTIONS FOR A RESILIENT CENTRAL ASIA',title_ru='РАЗВИТИЕ УМНЫХ И УСТОЙЧИВЫХ РЕШЕНИЙ ДЛЯ ЦЕНТРАЛЬНОЙ АЗИИ',body_en='Where climate innovation meets capital—spotlighting clean energy, sustainable infrastructure and technologies accelerating the region’s green transition.',body_ru='Здесь климатические инновации встречаются с капиталом: чистая энергетика, устойчивая инфраструктура и технологии ускоряют зелёный переход региона.' WHERE sort_order=4;
